import{_ as o,r as n,o as p,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Компоненты ( Components ) - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Псевдонимы","slug":"псевдонимы","link":"#псевдонимы","children":[]},{"level":2,"title":"Использование внешних значений","slug":"использование-внешних-значении","link":"#использование-внешних-значении","children":[]},{"level":2,"title":"Передача переменных в компонент","slug":"передача-переменных-в-компонент","link":"#передача-переменных-в-компонент","children":[]},{"level":2,"title":"Настройка шаблона по умолчанию","slug":"настроика-шаблона-по-умолчанию","link":"#настроика-шаблона-по-умолчанию","children":[{"level":3,"title":"Перемещение разметки во фрагмент","slug":"перемещение-разметки-во-фрагмент","link":"#перемещение-разметки-во-фрагмент","children":[]},{"level":3,"title":"Переопределение фрагментов компонента","slug":"переопределение-фрагментов-компонента","link":"#переопределение-фрагментов-компонента","children":[]}]},{"level":2,"title":"\\"View Bag\\"","slug":"view-bag","link":"#view-bag","children":[]}],"relativePath":"1.x/ru/cms/components.md","filePath":"1.x/ru/cms/components.md"}'),r={name:"1.x/ru/cms/components.md"};function u(g,a,d,m,k,h){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Компоненты ( Components )",-1)),s(e),a[1]||(a[1]=i(`<p>Компоненты - настраиваемые элементы, которые могут быть прикреплены к любой странице или шаблону. Компоненты являются ключевой особенностью OctoberCMS. Каждый компонент позволяет расширить возможности Вашего сайта. Их основные задачи заключаются в выводе HTML кода, обработке <a href="./../cms/ajax.html">AJAX запросов</a>, обработке форм и настройке отображения страниц.</p><p>Эта статья описывает основы работы с компонентами и не объясняет, как использовать их с AJAX. Эта тема описана в <a href="./../cms/ajax.html">AJAX</a>.</p><blockquote><p><strong>Примечание:</strong> Использование компонентов внутри фрагментов ограничивает их функционал (см. <a href="./partials.html#dynamic-partials">динамические фрагменты</a>).</p></blockquote><p><a name="introduction"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Если Вы используете административный интерфейс, то можете добавлять компоненты на страницы или шаблоны, кликнув по нему в панели <strong>Компоненты</strong>. Если же Вы используете текстовый редактор, то должны указать его название в <a href="./../cms/themes.html#configuration-section">Разделе Конфигурации</a>. Пример добавления компонента To-do на страницу:</p><div class="language- extra-class"><pre class="language-text"><code>title = &quot;Components demonstration&quot;
url = &quot;/components&quot;

[demoTodo]
maxItems = 20
==
...
</code></pre></div><p>Так инициализируется компонент с его свойствами, которые могут быть, а могут и не быть. Некоторые из них являются обязательными и имеют значения по умолчанию. Если Вы не уверены, какие свойства имеет компонент, то обратитесь к документации или используйте <strong>Инспектор</strong>. Он открывается при нажатии на компонент на странице или в панели с компонентами.</p><p>При добавлении компонента на страницу он автоматически создает переменную с таким же именем:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Примечание:</strong> Если два компонента с одинаковым именем добавлены на страницу и в шаблон, то первый из них перекроет свойства второго.</p></blockquote><p><a name="aliases"></a></p><h2 id="псевдонимы"><a href="#псевдонимы" class="header-anchor">#</a> Псевдонимы</h2><p>Если два плагина создают компоненты с одинаковыми именами, то Вы можете добавить их на страницу или шаблон, указав полный путь. Пример:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">October\\Demo\\Components\\Todo demoTodoAlias</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p>Первый параметр в секции - имя класса, второй - псевдоним, который используется в коде как ссылка на компонент. Пример:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Также псевдонимы позволяют определить несколько компонентов одного и того же класса на одной странице, указав сначала название компонента, после (через пробел) псевдоним. Пример:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoA</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoB</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p><a name="external-property-values"></a></p><h2 id="использование-внешних-значении"><a href="#использование-внешних-значении" class="header-anchor">#</a> Использование внешних значений</h2><p>По умолчанию свойства компонентов инициализируются в Разделе Настроек, где определен сам компонент:</p><pre><code>[demoTodo]
maxItems = 20
==
...
</code></pre><p>Однако, вы можете инициализировать свойства при помощи внешних значений - URL параметров или параметров <a href="./../cms/partials.html">фрагментов</a> (для компонентов, определенных во фрагментах). Используйте <code>{{ paramName }}</code> для значений, которые должы быть получены из переменных фрагмента:</p><div class="language- extra-class"><pre class="language-text"><code>[demoTodo]
maxItems = {{ maxItems }}
==
...
</code></pre></div><p>Предполагается, что в предыдущем примере компонент <strong>demoTodo</strong> находится во фрагменте и указана переменная <strong>maxItems</strong>:</p><div class="language- extra-class"><pre class="language-text"><code>{% partial &#39;my-todo-partial&#39; maxItems=&#39;10&#39; %}
</code></pre></div><p>Используйте <code>{{ :paramName }}</code>, чтобы получить значение из URL. Например:</p><div class="language- extra-class"><pre class="language-text"><code>[demoTodo]
maxItems = {{ :maxItems }}
==
...
</code></pre></div><p>Страница, на которой находится компонент, должна иметь <a href="./../cms/pages.html#url-syntax">соответствующий адрес</a>:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo/:maxItems</span>&quot;</span>
</code></pre></div><p>В административной части сайта Вы можете использовать Инспектора для привязки внешних значений к компоненту. Не используйте скобки <code>{{ }}</code>! Каждое свойство имеет иконку справа, при нажатии на которую, открывается поле для ввода значения, куда можно добавить название параметра <code>paramName</code> или <code>:paramName</code>.</p><p><a name="component-variables"></a></p><h2 id="передача-переменных-в-компонент"><a href="#передача-переменных-в-компонент" class="header-anchor">#</a> Передача переменных в компонент</h2><p>Components can be designed to use variables at the time they are rendered, similar to <a href="./partials.html#partial-variables">Partial variables</a>, they can be specified after the component name in the <code>{% component %}</code> tag. The specified variables will explicitly override the value of the <a href="./../plugin/components.html#component-properties">component properties</a>, including <a href="#external-property-values">external property values</a>.</p><p>In this example, the <strong>maxItems</strong> property of the component will be set to <em>7</em> at the time the component is rendered:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>7<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Not all components support passing variables when rendering.</p></blockquote><p><a name="customizing-default-markup"></a></p><h2 id="настроика-шаблона-по-умолчанию"><a href="#настроика-шаблона-по-умолчанию" class="header-anchor">#</a> Настройка шаблона по умолчанию</h2><p>Иногда Вы захотите изменить шаблон компонента (заменить текст, добавить изображение или т.п.). Для этого необходимо <a href="#moving-default-markup">переместить разметку компонента</a> по умолчанию во фрагмент или <a href="#overriding-partials">переопределить</a> ее.</p><p><a name="moving-default-markup"></a></p><h3 id="перемещение-разметки-во-фрагмент"><a href="#перемещение-разметки-во-фрагмент" class="header-anchor">#</a> Перемещение разметки во фрагмент</h3><p>Каждый компонент может иметь фрагмент <strong>default.htm</strong>, содержимое которого, замещает тег <code>{% component %}</code>. Пример:</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;blog/post&quot;

[blogPost]
==
{% component &quot;blogPost&quot; %}
</code></pre></div><p>Вы можете скопировать весь код из <strong>components/blogpost/default.htm</strong> и вставить его прямо в страницу или фрагмент, например, с названием <strong>blog-post.htm</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Внутри кода Вы можете найти переменную <code>__SELF__</code>, которая указывает на объект компонента. Она должна быть заменена на <strong>псевдоним</strong> (в нашем примере - это <strong>blogPost</strong>):</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Теперь вы можете добавить фрагмент в страницу или шаблон:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-post.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><a name="overriding-partials"></a></p><h3 id="переопределение-фрагментов-компонента"><a href="#переопределение-фрагментов-компонента" class="header-anchor">#</a> Переопределение фрагментов компонента</h3><p>Все фргаменты компонента могут быть переопределены, используя фрагменты темы. Если компонент называется <strong>channel</strong> и использует фрагмент <strong>title.htm</strong>:</p><pre><code>url = &quot;mypage&quot;

[channel]
==
{% component &quot;channel&quot; %}
</code></pre><p>Вы можете переопределить его, путем создания файла <strong>/themes/НАЗВАНИЕТЕМЫ/partials/ПСЕВДОНИМ/title.htm</strong>.</p><p><a name="viewbag-component"></a></p><h2 id="view-bag"><a href="#view-bag" class="header-anchor">#</a> &quot;View Bag&quot;</h2><p>В Октябре существует специальный компонент, который называется <code>viewBag</code> и который может использоваться на любой странице и любом шаблоне. В нем Вы можете заранее определить нужные вам переменные, после чего использовать их в коде. Например, указать активный пункт меню:</p><pre><code>title = &quot;About&quot;
url = &quot;/about.html&quot;
layout = &quot;default&quot;

[viewBag]
activeMenu = &quot;about&quot;
==

&lt;p&gt;Page content...&lt;/p&gt;
</code></pre><p>Получить его можно следующим образом::</p><div class="language- extra-class"><pre class="language-text"><code>description = &quot;Default layout&quot;
==
[...]

&lt;!-- Main navigation --&gt;
&lt;ul&gt;
    &lt;li class=&quot;{{ viewBag.activeMenu == &#39;about&#39; ? &#39;active&#39; }}&quot;&gt;About&lt;/li&gt;
    [...]
&lt;/ul&gt;
</code></pre></div><blockquote><p><strong>Примечание</strong>: viewBag скрыт в административной части сайта и может редактироваться только через текстовый редактор.</p></blockquote><blockquote><p><strong>Примечание</strong>: viewBag могут использовать другие плагины.</p></blockquote>`,64))])}const w=o(r,[["render",u]]);export{x as __pageData,w as default};
